        commentlines=0, printdir=0, fulllayout=0, codetags=(), comment="", eol='$',
        magic="flf2", extra=""):
    """glyphs: dict char->list of rows (each row string, no eol)"""
    if baseline is None: baseline = height
    rows = sorted(glyphs.keys(), key=lambda c: ord(c))
    if maxlen is None: maxlen = max(max(len(r) for r in g) for g in glyphs.values())
    # need contiguous codes from 32..126 plus 6 umlauts
    need = [32]
    for c in range(33,127): need.append(c)
    need += [196,214,220,228,246,252]
    body=[]
    for k in need:
        g = glyphs.get(chr(k))
        if g is None:
            g = [' ']*height
        if len(g) < height:
            g = g + [' '*(maxlen-len(g[0]))]*(height-len(g))
        for r in g:
            body.append(r+eol)
        body[-1] += '@'
    lines=[magic+eol+" %d %d %d %d %d %d %d %d"%(height,baseline,maxlen,oldlayout,commentlines,printdir,fulllayout,len(codetags))]
    if comment:
        for c in comment.split('\n'): lines.append(c)
    lines += body
    for t in codetags: lines.append(t)
    open(path,'w').write('\n'.join(lines)+'\n')
