/* ---------- german (deutsch) processing ---------- */
static int deutschflag = 0;
static int deutsch(int c)
{
    if (!deutschflag) return c;
    switch (c) {
    case '[': return 196;
    case '\\': return 214;
    case ']': return 220;
    case '{': return 228;
    case '|': return 246;
    case '}': return 252;
    case '~': return 223;
    }
    return c;
}

/* ---------- output ---------- */
static char **outline = NULL;
static int outlinelen = 0;
static int outlinesize = 0;

static void outline_init(void)
{
    if (!outline) {
        outline = xmalloc(sizeof(char*)*charheight);
        int i; for (i=0;i<charheight;i++) outline[i]=xmalloc(8);
        outlinelen = 0; outlinesize = 8;
    }
}
static void outline_resize(int need)
{
    if (need <= outlinesize) return;
    int new = outlinesize;
    while (new < need) new *= 2;
    int i; for (i=0;i<charheight;i++) { outline[i]=realloc(outline[i],new+1); if(!outline[i]){fprintf(stderr,"Out of memory\n");exit(1);} }
    outlinesize = new;
}

/* character classes for hierarchy smushing */
static int hclass(int c)
{
    switch (c) {
    case '|': return 1;
    case '/': case '\\': return 2;
    case '[': case ']': return 3;
    case '{': case '}': return 4;
    case '(': case ')': return 5;
    case '<': case '>': return 6;
    }
    return 0;
}

static int smushmode = 0;      /* effective mode: 0..63 rules, 0x40/0x80 overlap */

/* returns the merged character, or 0 if the pair cannot be merged */
static int smush(int ch1, int ch2, int mode)
{
    int hb = hardblank;
    if (ch1 == ' ') return ch2;
    if (ch2 == ' ') return ch1;
    if (mode & 0x01) { if (ch1 == ch2 && ch1 != hb) return ch1; }
    if (mode & 0x02) { /* underscore */
        if (ch1 == '_' && ch2 != hb && hclass(ch2)) return ch2;
        if (ch2 == '_' && ch1 != hb && hclass(ch1)) return ch1;
    }
    if (mode & 0x04) {
        int c1 = hclass(ch1), c2 = hclass(ch2);
        if (c1 && c2 && c1 != c2) return (c1>c2)?ch1:ch2;
    }
    if (mode & 0x08) {
        if ((ch1=='['&&ch2==']')||(ch1==']'&&ch2=='[')||
            (ch1=='{'&&ch2=='}')||(ch1=='}'&&ch2=='{')||
            (ch1=='('&&ch2==')')||(ch1==')'&&ch2=='(')) return '|';
    }
    if (mode & 0x10) {
        if (ch1=='/'&&ch2=='\\') return '|';
        if (ch1=='\\'&&ch2=='/') return 'Y';
        if (ch1=='>'&&ch2=='<') return 'X';
    }
    if (mode & 0x20) {
        if (ch1 == hb && ch2 == hb) return hb;
    }
    if (mode & 0xC0) {
        if (ch1 == hb) return ch2;
        if (ch2 == hb) return ch1;
        return ch2;
    }
    return 0;   /* cannot smush */
}

static int smushable(int ch1, int ch2, int mode)
{
    if (ch1 == ' ' || ch2 == ' ') return 1;
    return smush(ch1,ch2,mode) != 0;
}

/* compute kerning/overlap amount for adding char c */
static int compute_smush(FIGchar *fc, int mode, int kern_only)
{
    int cw = fc->width;
    int row;
    int best = 0;
    int limit = cw;
    if (mode & 0xC0) limit = cw;  /* overlap may go 1 further; handled below */
    for (row=0; row<charheight; row++) {
        const char *o = outline[row];
        const char *nr = fc->rows[row];
        int tb = 0;
        while (tb < outlinelen && o[outlinelen-1-tb]==' ') tb++;
        int lb = 0;
        while (lb < cw && nr[lb]==' ') lb++;
        int k = tb + lb;
        if (mode & 0xC0) {
            if (cw >= 2) k = tb + lb + 1;
            else k = tb + lb;
            if (outlinelen < 2) k = tb + lb;   /* observed: no extra overlap */
        }
        if (k > cw) k = cw;
        if (best == 0 || k < best) best = k;
    }
    if (best < 0) best = 0;
    if (best > outlinelen + cw) best = outlinelen + cw;
    return best;
}

static void addchar(int c);

static void printline(void)
{
    int row;
    int maxw = 0;
    for (row=0;row<charheight;row++) { int l=strlen(outline[row]); if(l>maxw) maxw=l; }
    /* trim leading blank columns */
    if (!(smushmode & 0x100)) {  /* not full width */
        int trim = 0;
        int col;
        for (col=0; col<maxw; col++) {
            int allblank = 1, r;
            for (r=0;r<charheight;r++) {
                char ch = (col < (int)strlen(outline[r])) ? outline[r][col] : ' ';
                if (ch != ' ') { allblank = 0; break; }
            }
            if (!allblank) break;
            trim++;
        }
        if (trim) {
            for (row=0;row<charheight;row++) {
                int l=strlen(outline[row]);
                int i;
                for (i=0;i+trim<=l;i++) outline[row][i]=outline[row][i+trim];
                outline[row][l-trim]=0;
            }
            outlinelen -= trim;
            maxw -= trim;
        }
    }
    if (justification == J_CENTER) { ... }
}
